import { useState } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, softDelete } from '@/db/db'
import { moduleLinksFor, otherModulesFor, type ModuleLink } from '@/app/nav'
import { MENTAL_LOAD_TYPES, type Bill, type MentalLoadType, type SplitModel, type Stage, type Task } from '@/types/domain'
import { useI18n } from '@/i18n'
import { formatRupiah, mentalLoadLabel, whenLabel } from '@/i18n/format'
import { Groceries } from './Groceries'
import { Contacts, Documents } from './Documents'
import { Goals, MoneyMeetingCard } from '@/features/finance/Goals'
import { useT } from '@/i18n'

/**
 * Kehidupan — tasks, mental load, and bills (HOME-01/02, FIN-01/02/04).
 *
 * The mental-load breakdown is the point of this screen: a tally of who
 * *did* things hides who noticed, remembered, planned, and chased them.
 */
export default function Household() {
  const { t, locale } = useI18n()
  const { profile, profiles } = useSession()
  const me = profile?.id
  const [params, setParams] = useSearchParams()
  const [sheet, setSheet] = useState<'task' | 'bill' | null>((params.get('baru') as 'task' | 'bill') ?? null)

  const tasks = useOwned<Task>('tasks', me)
  const bills = useOwned<Bill>('bills', me)

  if (!profile || !me) return null

  const open = (tasks ?? []).filter((t) => t.status !== 'done')
  const done = (tasks ?? []).filter((t) => t.status === 'done')
  const unpaid = (bills ?? []).filter((b) => b.status === 'unpaid').sort((a, b) => a.dueDate.localeCompare(b.dueDate))

  function close() {
    setSheet(null)
    if (!params.has('baru')) return
    params.delete('baru')
    setParams(params, { replace: true })
  }

  return (
    <div className="stack">
      <h1>{t('home.title')}</h1>

      <MentalLoadBreakdown tasks={tasks ?? []} profiles={profiles} />

      <Card
        title={t('home.tasks')}
        icon="tasks"
        action={
          <button className="btn btn--sm" onClick={() => setSheet('task')}>
            <Icon name="plus" size={16} /> {t('quick.task')}
          </button>
        }
        hint={t('home.tasksHint')}
      >
        {open.length === 0 ? (
          <EmptyState sticker="empty-list" title={t('home.noTasks')} hint={t('today.noRunningHint')} />
        ) : (
          <ul className="list">
            {open.map((task) => {
              const owner = profiles.find((p) => p.id === task.accountableProfileId)
              return (
                <li key={task.id} className="list__item">
                  <button
                    className="btn btn--ghost btn--sm btn--icon"
                    aria-label={t('home.markDone', { name: task.title })}
                    onClick={() =>
                      db.tasks.update(task.id, { status: 'done', completedAt: new Date().toISOString() })
                    }
                  >
                    <Icon name="check" size={16} />
                  </button>
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{task.title}</strong>
                    <span className="card__hint">
                      {owner?.displayName ?? t('home.noPic')} · {mentalLoadLabel(task.mentalLoadType, t)}
                      {task.dueDate ? ` · ${whenLabel(task.dueDate, t, locale)}` : ''}
                    </span>
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('tasks', task.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: task.title })} />
                  </button>
                </li>
              )
            })}
          </ul>
        )}
        {done.length > 0 && (
          <details style={{ marginTop: 'var(--space-2)' }}>
            <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
              {t('home.doneCount', { n: done.length })}
            </summary>
            <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
              {done.slice(0, 12).map((task) => (
                <li key={task.id} className="list__item">
                  <Icon name="check" size={16} />
                  <span className="grow" style={{ color: 'var(--muted)' }}>{task.title}</span>
                  <button
                    className="btn btn--ghost btn--sm"
                    onClick={() => db.tasks.update(task.id, { status: 'todo', completedAt: undefined })}
                  >
                    {t('home.undo')}
                  </button>
                </li>
              ))}
            </ul>
          </details>
        )}
      </Card>

      <Card
        title={t('fin.bills')}
        icon="money"
        action={
          <button className="btn btn--sm" onClick={() => setSheet('bill')}>
            <Icon name="plus" size={16} /> {t('quick.bill')}
          </button>
        }
        hint={t('fin.billsHint')}
      >
        {unpaid.length === 0 ? (
          <EmptyState sticker="empty-money" title={t('fin.noBills')} />
        ) : (
          <ul className="list">
            {unpaid.map((b) => (
              <li key={b.id} className="list__item">
                <Icon name="money" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{b.title}</strong>
                  <span className="card__hint">
                    {formatRupiah(b.amount, locale)} · {whenLabel(b.dueDate, t, locale)} ·{' '}
                    {t(`fin.space.${b.space}` as const)}
                    {b.installmentOf
                      ? ` · ${t('fin.installment', {
                          i: b.installmentOf.index,
                          total: b.installmentOf.total,
                        })}`
                      : ''}
                  </span>
                </span>
                <button
                  className="btn btn--soft btn--sm"
                  onClick={() => db.bills.update(b.id, { status: 'paid', paidAt: new Date().toISOString() })}
                >{t('fin.paid')}
                </button>
              </li>
            ))}
          </ul>
        )}
        <p className="disclaimer" style={{ marginTop: 'var(--space-2)' }}>
          {t('fin.disclaimer')}
        </p>
      </Card>

      <Groceries me={me} profiles={profiles} />

      <Goals me={me} />

      <MoneyMeetingCard me={me} />

      <Documents me={me} />

      <Contacts me={me} />

      <ModuleShelf stage={profile.stage} />

      <TaskSheet open={sheet === 'task'} onClose={close} me={me} profiles={profiles} />
      <BillSheet open={sheet === 'bill'} onClose={close} me={me} profiles={profiles} />
    </div>
  )
}

/**
 * Everything that did not fit the five-item shelf. Kehidupan is the documented
 * overflow hub (see `app/nav.ts`), so one list here is what keeps every module
 * reachable without a sixth tab nobody can hit at 320 px.
 */
function ModuleGrid({ links }: { links: ModuleLink[] }) {
  const t = useT()
  return (
    <div className="modgrid">
      {links.map((m) => (
        <Link key={m.to} to={m.to} className="modcard">
          <span className="modcard__ic">
            <Icon name={m.icon} size={22} />
          </span>
          <span className="modcard__body">
            <strong>{t(m.label)}</strong>
            <small>{t(m.desc)}</small>
          </span>
          <Icon name="chevron-right" size={16} className="modcard__go" />
        </Link>
      ))}
    </div>
  )
}

/**
 * Every module in the app, as cards rather than a list of links.
 *
 * Two things were wrong before. It rendered a bare text list, which is why the
 * app read as "just words"; and it filtered by stage, so picking "pacaran" hid
 * the wedding planner, the money spaces and the fertility screens completely —
 * fifteen features looked like five. Now the stage only decides the ORDER, and
 * a second group makes it obvious the rest are there too.
 */
function ModuleShelf({ stage }: { stage: Stage }) {
  const t = useT()
  const suggested = moduleLinksFor(stage)
  const others = otherModulesFor(stage)
  return (
    <Card title={t('mod.all')} icon="shared" hint={t('mod.allHint')}>
      {suggested.length > 0 && (
        <>
          <p className="modgroup">{t('mod.suggested')}</p>
          <ModuleGrid links={suggested} />
        </>
      )}
      {others.length > 0 && (
        <>
          <p className="modgroup">{t('mod.others')}</p>
          <ModuleGrid links={others} />
        </>
      )}
    </Card>
  )
}


/** HOME-02 — makes invisible work visible instead of counting chores. */
function MentalLoadBreakdown({
  tasks,
  profiles,
}: {
  tasks: Task[]
  profiles: { id: string; displayName: string }[]
}) {
  const t = useT()

  if (tasks.length === 0) return null
  const rows = profiles.map((p) => ({
    name: p.displayName,
    counts: MENTAL_LOAD_TYPES.map(
      (t) => tasks.filter((x) => x.accountableProfileId === p.id && x.mentalLoadType === t).length,
    ),
    total: tasks.filter((x) => x.accountableProfileId === p.id).length,
  }))

  return (
    <Card title={t('home.mentalLoad')} icon="mentalload" hint={t('home.mentalLoadHint')}>
      <div className="table-scroll">
      <table>
        <caption className="visually-hidden">
          {t('home.mentalLoadCaption')}
        </caption>
        <thead>
          <tr>
            <th scope="col" style={th}>{t('home.who')}</th>
            {MENTAL_LOAD_TYPES.map((kind) => (
              <th key={kind} scope="col" style={{ ...th, textAlign: 'center' }}>
                {mentalLoadLabel(kind, t)}
              </th>
            ))}
            <th scope="col" style={{ ...th, textAlign: 'center' }}>{t('home.total')}</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.name}>
              <th scope="row" style={td}>{r.name}</th>
              {r.counts.map((c, i) => (
                <td key={i} style={{ ...td, textAlign: 'center' }}>{c}</td>
              ))}
              <td style={{ ...td, textAlign: 'center', fontWeight: 800 }}>{r.total}</td>
            </tr>
          ))}
        </tbody>
      </table>
      </div>
    </Card>
  )
}

const th: React.CSSProperties = { textAlign: 'left', padding: '5px 4px', borderBottom: '1px solid var(--border)', fontWeight: 800, fontSize: 12 }
const td: React.CSSProperties = { textAlign: 'left', padding: '5px 4px', borderBottom: '1px solid var(--border)', fontWeight: 400 }

function TaskSheet({
  open,
  onClose,
  me,
  profiles,
}: {
  open: boolean
  onClose: () => void
  me: string
  profiles: { id: string; displayName: string }[]
}) {
  const t = useT()
  const [title, setTitle] = useState('')
  const [owner, setOwner] = useState(me)
  const [load, setLoad] = useState<MentalLoadType>('do')
  const [due, setDue] = useState('')

  async function save() {
    if (!title.trim()) return
    await db.tasks.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'task',
      title: title.trim(),
      accountableProfileId: owner,
      helperProfileIds: [],
      mentalLoadType: load,
      ...(due ? { dueDate: due } : {}),
      status: 'todo',
    } as never)
    setTitle('')
    setDue('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('home.newTask')}>
      <div className="stack">
        <Field label={t('home.taskWhat')}>
          {(p) => <input {...p} type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t('home.taskPlaceholder')} />}
        </Field>
        <Field label={t('common.who')} hint={t('home.whoHint')}>
          {(p) => (
            <select {...p} value={owner} onChange={(e) => setOwner(e.target.value)}>
              {profiles.map((x) => (
                <option key={x.id} value={x.id}>
                  {x.displayName}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('home.loadKind')} hint={t('home.loadHint')}>
          {(p) => (
            <select {...p} value={load} onChange={(e) => setLoad(e.target.value as MentalLoadType)}>
              {MENTAL_LOAD_TYPES.map((kind) => (
                <option key={kind} value={kind}>
                  {mentalLoadLabel(kind, t)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('home.deadline')} hint={t('common.optional')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!title.trim()}>
          {t('home.saveTask')}
        </button>
      </div>
    </Sheet>
  )
}

function BillSheet({
  open,
  onClose,
  me,
  profiles,
}: {
  open: boolean
  onClose: () => void
  me: string
  profiles: { id: string; displayName: string }[]
}) {
  const t = useT()
  const [title, setTitle] = useState('')
  const [amount, setAmount] = useState('')
  const [due, setDue] = useState(format(new Date(), 'yyyy-MM-dd'))
  const [space, setSpace] = useState<Bill['space']>('shared')
  const [split, setSplit] = useState<SplitModel>('equal')
  const [payer, setPayer] = useState(me)

  async function save() {
    const n = Number(amount)
    if (!title.trim() || !Number.isFinite(n) || n <= 0) return
    await db.bills.add({
      ...newEnvelope(me, space === 'shared' ? 'C2_shared_ops' : 'C1_personal', {
        visibility: space === 'shared' ? 'shared' : 'private',
      }),
      kind: 'bill',
      title: title.trim(),
      amount: n,
      currency: 'IDR',
      dueDate: due,
      payerProfileId: payer,
      splitModel: split,
      status: 'unpaid',
      space,
    } as never)
    setTitle('')
    setAmount('')
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('fin.newBill')}>
      <div className="stack">
        <Field label={t('fin.billWhat')}>
          {(p) => <input {...p} type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t('fin.billPlaceholder')} />}
        </Field>
        <Field label={t('common.rupiah')}>
          {(p) => (
            <input {...p} type="number" inputMode="numeric" min="0" value={amount} onChange={(e) => setAmount(e.target.value)} />
          )}
        </Field>
        <Field label={t('fin.dueDate')}>{(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}</Field>
        <Field label={t('fin.space')} hint={t('fin.spaceHint')}>
          {(p) => (
            <select {...p} value={space} onChange={(e) => setSpace(e.target.value as Bill['space'])}>
              <option value="shared">{t('fin.space.shared')}</option>
              <option value="mine">{t('fin.space.mine')}</option>
              <option value="partner">{t('fin.space.partner')}</option>
            </select>
          )}
        </Field>
        {space === 'shared' && (
          <>
            <Field label={t('fin.split')} hint={t('fin.splitHint')}>
              {(p) => (
                <select {...p} value={split} onChange={(e) => setSplit(e.target.value as SplitModel)}>
                  <option value="equal">{t('fin.split.equal')}</option>
                  <option value="proportional">{t('fin.split.proportional')}</option>
                  <option value="alternating">{t('fin.split.alternating')}</option>
                  <option value="custom">{t('fin.split.custom')}</option>
                </select>
              )}
            </Field>
            <Field label={t('fin.payer')}>
              {(p) => (
                <select {...p} value={payer} onChange={(e) => setPayer(e.target.value)}>
                  {profiles.map((x) => (
                    <option key={x.id} value={x.id}>
                      {x.displayName}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}
        <button className="btn btn--block" onClick={save} disabled={!title.trim() || !amount}>
          {t('fin.saveBill')}
        </button>
      </div>
    </Sheet>
  )
}
