import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useT } from '@/i18n'
import type { GroceryItem } from '@/types/domain'

/**
 * Belanjaan (HOME-03).
 *
 * A shared checklist. Ticking an item is one tap and reversible, because the
 * common failure mode is someone tapping the wrong row in a shop aisle.
 */
export function Groceries({
  me,
  profiles,
}: {
  me: string
  profiles: { id: string; displayName: string }[]
}) {
  const t = useT()
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [qty, setQty] = useState('')
  const [buyer, setBuyer] = useState('')

  const items = useOwned<GroceryItem>('groceries', me)
  const todo = (items ?? []).filter((i) => !i.bought)
  const bought = (items ?? []).filter((i) => i.bought)

  async function save() {
    if (!name.trim()) return
    await db.groceries.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'grocery',
      name: name.trim(),
      ...(qty.trim() ? { quantity: qty.trim() } : {}),
      ...(buyer ? { usualBuyerProfileId: buyer } : {}),
      bought: false,
    } as never)
    setName('')
    setQty('')
    setOpen(false)
  }

  async function toggle(item: GroceryItem) {
    await patch('groceries', item.id, {
      bought: !item.bought,
      boughtAt: item.bought ? undefined : new Date().toISOString(),
    })
  }

  return (
    <Card
      title={t('home.groceries')}
      icon="groceries"
      hint={t('home.groceriesHint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('common.add')}
        </button>
      }
    >
      {todo.length === 0 && bought.length === 0 ? (
        <EmptyState icon="groceries" title={t('home.noGroceries')} hint={t('home.noGroceriesHint')} />
      ) : (
        <ul className="list">
          {todo.map((i) => (
            <li key={i.id} className="list__item">
              <button
                className="btn btn--ghost btn--sm btn--icon"
                aria-label={t('home.markDone', { name: i.name })}
                onClick={() => toggle(i)}
              >
                <Icon name="check" size={16} />
              </button>
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{i.name}</strong>
                {(i.quantity || i.usualBuyerProfileId) && (
                  <span className="card__hint">
                    {i.quantity}
                    {i.quantity && i.usualBuyerProfileId ? ' · ' : ''}
                    {profiles.find((p) => p.id === i.usualBuyerProfileId)?.displayName ?? ''}
                  </span>
                )}
              </span>
              <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('groceries', i.id, me)}>
                <Icon name="close" size={16} label={t('common.deleteX', { name: i.name })} />
              </button>
            </li>
          ))}
        </ul>
      )}

      {bought.length > 0 && (
        <details style={{ marginTop: 'var(--space-2)' }}>
          <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
            {t('home.groceryBought', { n: bought.length })}
          </summary>
          <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
            {bought.map((i) => (
              <li key={i.id} className="list__item">
                <Icon name="check" size={16} />
                <span className="grow" style={{ color: 'var(--muted)' }}>
                  {i.name}
                </span>
                <button className="btn btn--ghost btn--sm" onClick={() => toggle(i)}>
                  {t('home.undo')}
                </button>
              </li>
            ))}
          </ul>
          <button
            className="btn btn--ghost btn--sm"
            style={{ marginTop: 'var(--space-2)' }}
            onClick={() => Promise.all(bought.map((i) => softDelete('groceries', i.id, me)))}
          >
            {t('home.clearBought')}
          </button>
        </details>
      )}

      <Sheet open={open} onClose={() => setOpen(false)} title={t('home.groceries')}>
        <div className="stack">
          <Field label={t('home.groceryItem')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={name}
                placeholder={t('home.groceryPlaceholder')}
                onChange={(e) => setName(e.target.value)}
              />
            )}
          </Field>
          <Field label={t('home.groceryQty')} hint={t('common.optional')}>
            {(p) => <input {...p} type="text" value={qty} onChange={(e) => setQty(e.target.value)} />}
          </Field>
          {profiles.length > 1 && (
            <Field label={t('home.boughtBy')} hint={t('common.optional')}>
              {(p) => (
                <select {...p} value={buyer} onChange={(e) => setBuyer(e.target.value)}>
                  <option value="">—</option>
                  {profiles.map((x) => (
                    <option key={x.id} value={x.id}>
                      {x.displayName}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          )}
          <button className="btn btn--block" onClick={save} disabled={!name.trim()}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </Card>
  )
}
