import { useState } from 'react'
import { differenceInCalendarDays, format, parseISO } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, softDelete } from '@/db/db'
import { useI18n } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import { DOCUMENT_KINDS, type DocumentKind, type EmergencyContact, type HouseholdDocument } from '@/types/domain'

/**
 * Dokumen rumah tangga (HOME-04) and kontak darurat (HOME-05).
 *
 * Documents are metadata only — no scans, no uploads. A photo of an ID sitting
 * in a shared-phone database is a liability the app cannot protect, so it does
 * not accept one. The reference field is optional and carries a warning.
 */

/** Anything expiring inside this window gets flagged. */
const SOON_DAYS = 30

export function Documents({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [docKind, setDocKind] = useState<DocumentKind>('vehicle')
  const [reference, setReference] = useState('')
  const [expires, setExpires] = useState('')

  const docs = useOwned<HouseholdDocument>('documents', me, (a, b) =>
    (a.expiresAt ?? '9999').localeCompare(b.expiresAt ?? '9999'),
  )

  async function save() {
    if (!name.trim()) return
    await db.documents.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'document',
      name: name.trim(),
      docKind,
      ...(reference.trim() ? { reference: reference.trim() } : {}),
      ...(expires ? { expiresAt: expires } : {}),
    } as never)
    setName('')
    setReference('')
    setExpires('')
    setOpen(false)
  }

  function status(d: HouseholdDocument): { label: string; chip: string } | null {
    if (!d.expiresAt) return null
    const days = differenceInCalendarDays(parseISO(d.expiresAt), new Date())
    if (days < 0) return { label: t('home.docExpired'), chip: 'chip--primary' }
    if (days <= SOON_DAYS) return { label: t('home.docSoon'), chip: 'chip--yellow' }
    return null
  }

  return (
    <Card
      title={t('home.docs')}
      icon="private"
      hint={t('home.docsHint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('common.add')}
        </button>
      }
    >
      {(docs ?? []).length === 0 ? (
        <EmptyState icon="private" title={t('home.noDocs')} hint={t('home.noDocsHint')} />
      ) : (
        <ul className="list">
          {(docs ?? []).map((d) => {
            const s = status(d)
            return (
              <li key={d.id} className="list__item">
                <Icon name="private" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{d.name}</strong>
                  <span className="card__hint">
                    {t(`doc.${d.docKind}` as const)}
                    {d.expiresAt ? ` · ${whenLabel(d.expiresAt, t, locale)}` : ''}
                    {d.reference ? ` · ${d.reference}` : ''}
                  </span>
                </span>
                {s && <span className={`chip ${s.chip}`}>{s.label}</span>}
                <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('documents', d.id, me)}>
                  <Icon name="close" size={16} label={t('common.deleteX', { name: d.name })} />
                </button>
              </li>
            )
          })}
        </ul>
      )}

      <Sheet open={open} onClose={() => setOpen(false)} title={t('home.docs')}>
        <div className="stack">
          <Field label={t('home.docName')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={name}
                placeholder={t('home.docPlaceholder')}
                onChange={(e) => setName(e.target.value)}
              />
            )}
          </Field>
          <Field label={t('home.docKind')}>
            {(p) => (
              <select {...p} value={docKind} onChange={(e) => setDocKind(e.target.value as DocumentKind)}>
                {DOCUMENT_KINDS.map((k) => (
                  <option key={k} value={k}>
                    {t(`doc.${k}` as const)}
                  </option>
                ))}
              </select>
            )}
          </Field>
          <Field label={t('home.docExpires')} hint={t('common.optional')}>
            {(p) => <input {...p} type="date" value={expires} onChange={(e) => setExpires(e.target.value)} />}
          </Field>
          <Field label={t('home.docNumber')} hint={t('home.docNumberHint')}>
            {(p) => (
              <input {...p} type="text" value={reference} onChange={(e) => setReference(e.target.value)} />
            )}
          </Field>
          <button className="btn btn--block" onClick={save} disabled={!name.trim()}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </Card>
  )
}

export function Contacts({ me }: { me: string }) {
  const t = useI18n().t
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [relation, setRelation] = useState('')
  const [phone, setPhone] = useState('')

  const contacts = useOwned<EmergencyContact>('contacts', me)

  async function save() {
    if (!name.trim() || !phone.trim()) return
    await db.contacts.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'contact',
      name: name.trim(),
      relation: relation.trim(),
      phone: phone.trim(),
    } as never)
    setName('')
    setRelation('')
    setPhone('')
    setOpen(false)
  }

  return (
    <Card
      title={t('home.contacts')}
      icon="emergency"
      hint={t('home.contactsHint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('common.add')}
        </button>
      }
    >
      {(contacts ?? []).length === 0 ? (
        <EmptyState icon="emergency" title={t('home.noContacts')} hint={t('home.noContactsHint')} />
      ) : (
        <ul className="list">
          {(contacts ?? []).map((c) => (
            <li key={c.id} className="list__item">
              <Icon name="emergency" size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{c.name}</strong>
                <span className="card__hint">{c.relation}</span>
              </span>
              {/* A tel: link works offline and hands off to the dialer. */}
              <a className="btn btn--soft btn--sm" href={`tel:${c.phone.replace(/\s/g, '')}`}>
                <Icon name="emergency" size={16} />
                <span className="visually-hidden">{t('home.call', { name: c.name })}</span>
                {c.phone}
              </a>
              <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('contacts', c.id, me)}>
                <Icon name="close" size={16} label={t('common.deleteX', { name: c.name })} />
              </button>
            </li>
          ))}
        </ul>
      )}

      <Sheet open={open} onClose={() => setOpen(false)} title={t('home.contacts')}>
        <div className="stack">
          <Field label={t('home.contactName')}>
            {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
          </Field>
          <Field label={t('home.contactRelation')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={relation}
                placeholder={t('home.contactRelationPlaceholder')}
                onChange={(e) => setRelation(e.target.value)}
              />
            )}
          </Field>
          <Field label={t('home.contactPhone')}>
            {(p) => (
              <input {...p} type="tel" inputMode="tel" value={phone} onChange={(e) => setPhone(e.target.value)} />
            )}
          </Field>
          <button className="btn btn--block" onClick={save} disabled={!name.trim() || !phone.trim()}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </Card>
  )
}

export { format }
